function closeToast(id){const el=document.getElementById(id);if(el){el.style.opacity='0';el.style.transform='translateX(20px)';setTimeout(()=>el.remove(),400);}}
setTimeout(()=>{document.querySelectorAll('.toast-item').forEach(t=>closeToast(t.id));},5000);;$(".form").find("input, select").on("focus blur change keyup",function(){const label=$(this).prev("label");if($(this).val()){label.addClass("active");}else{label.removeClass("active");}});$(".tab a").on("click",function(e){e.preventDefault();$(".tab").removeClass("active");$(this).parent().addClass("active");$(".tab-content > div").hide().removeClass("active");const target=$(this).attr("href");$(target).fadeIn(200).addClass("active");$(target).find("input:first").focus();});;